import { signal } from '@pyreon/reactivity'
import { useDocumentVisibility, useInterval, useOnline, useTimeAgo } from '@pyreon/hooks'

export function LiveScore(props: { load: () => Promise<number> }) {
  const score = signal(0)
  const updated = signal(Date.now())
  const visibility = useDocumentVisibility()
  const online = useOnline()

  const refresh = async () => {
    score.set(await props.load())
    updated.set(Date.now())
  }

  // Polls every 10 s, pauses while the tab is hidden or the network is gone.
  useInterval(refresh, () => (visibility() === 'visible' && online() ? 10_000 : null))
  const ago = useTimeAgo(() => updated())

  return (
    <p>
      {() => score()} · updated {() => ago()}
      {() => (online() ? null : ' · offline, paused')}
    </p>
  )
}

import { useClipboard, useHaptics, useShare } from '@pyreon/hooks'
import { Button } from '@pyreon/primitives'

export function ShareButton(props: { url: string }) {
  const share = useShare()
  const clipboard = useClipboard()
  const haptics = useHaptics()

  const onPress = async () => {
    haptics.impact('light')
    if (share.canShare()) share.url(props.url)
    else await clipboard.copy(props.url)
  }

  return (
    <Button onPress={onPress}>
      {clipboard.copied() ? 'Link copied' : 'Share'}
    </Button>
  )
}
